import{createClient}from"@/lib/supabase/server";import VendorClient from"./VendorClient";import Link from"next/link";export default async function Vendor(){const s=await createClient();const{data:{user}}=await s.auth.getUser();if(!user)return <main className="shell"><Link className="btn" href="/auth">Sign in</Link></main>;const{data:p}=await s.from("profiles").select("role").eq("id",user.id).maybeSingle();if(p?.role!=="vendor"&&p?.role!=="admin")return <main className="shell"><h1>Vendor portal</h1><p>Your account is not an approved vendor.</p></main>;const{data:v}=await s.from("vendor_profiles").select("*").eq("user_id",user.id).maybeSingle();if(!v)return <main className="shell"><h1>Vendor portal</h1><p>No vendor profile found.</p></main>;const{data:o}=await s.from("orders").select("*").eq("vendor_user_id",user.id).neq("status","delivered").order("created_at",{ascending:false});return <main className="shell"><h1>Vendor portal</h1><VendorClient vendor={v} orders={o||[]}/></main>}